CREATE TABLE IF NOT EXISTS performance_cycles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS performance_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, cycle_id uuid REFERENCES performance_cycles(id) ON DELETE SET NULL, title text NOT NULL, description text, target numeric(12,2), progress numeric(12,2) NOT NULL DEFAULT 0, weight numeric(6,2) NOT NULL DEFAULT 100, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS performance_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, cycle_id uuid REFERENCES performance_cycles(id) ON DELETE SET NULL, reviewer_id uuid, rating numeric(4,2), strengths text, development_areas text, recommendation text, status text NOT NULL DEFAULT 'draft', reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, work_date date NOT NULL, check_in timestamptz, check_out timestamptz, status text NOT NULL DEFAULT 'present', hours numeric(6,2), UNIQUE(person_id,work_date));
CREATE TABLE IF NOT EXISTS leave_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, annual_days numeric(6,2) NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS leave_balances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, policy_id uuid NOT NULL REFERENCES leave_policies(id) ON DELETE CASCADE, year int NOT NULL, entitled numeric(6,2) NOT NULL DEFAULT 0, used numeric(6,2) NOT NULL DEFAULT 0, UNIQUE(person_id,policy_id,year));
CREATE INDEX IF NOT EXISTS idx_perf_goals_person ON performance_goals(person_id); CREATE INDEX IF NOT EXISTS idx_reviews_person ON performance_reviews(person_id); CREATE INDEX IF NOT EXISTS idx_attendance_person_date ON attendance_records(person_id,work_date);